R=Path(__file__).resolve().parents[1]
def select(id,label,opts):return '<label for="'+id+'">'+label+'<select id="'+id+'">'+''.join('<option value="'+str(v)+'">'+str(t)+'</option>' for v,t in opts)+'</select></label>'
def slider(id,label,a,b,step,v):return f'<label for="{id}">{label} <output id="{id}-out">{v}</output><input id="{id}" type="range" min="{a}" max="{b}" step="{step}" value="{v}"></label>'
def button(id,t):return f'<button id="{id}">{t}</button>'
def lab(id,num,title,prompt,controls,extra='',canvas=True,note=''):
 return f'''<section class="demo" id="{id}-lab" aria-labelledby="{id}-title"><header class="demo-head"><div><div class="demo-no">INTERACTIVE {num} / 观察 · 预测 · 验证</div><h4 id="{id}-title">{title}</h4></div><button data-play aria-pressed="true">暂停动画</button></header><div class="prompt">{prompt}</div><div class="demo-body">{'<canvas role="img" aria-label="'+title+'，可拖动改变相机"></canvas><div class="camera-note">拖动改变相机 · 滚轮缩放 · 操作终点才用于判断对称性</div>' if canvas else ''}<div class="controls">{controls}</div>{extra}<div class="result" id="{id}-status" role="status" aria-live="off">载入计算结果。</div><p class="note">{note}</p><details class="source-box"><summary>查看这个模型的计算代码</summary><pre><code data-source="{id}"></code></pre><div class="source-links"><a href="assets/symmetry.js" download>完整变换核心JS ↓</a><a href="examples.py" download>NumPy复现代码 ↓</a></div></details></div></section>'''
models=[('water','水 H₂O'),('ammonia','氨 NH₃'),('bf3','平面 BF₃'),('methane','正四面体 CH₄'),('sf6','正八面体 SF₆'),('square','平面 [PtCl₄]²⁻'),('benzene','苯'),('pf5','三角双锥 PF₅'),('allene','丙二烯'),('ethane','交错乙烷'),('ferrocene','交错二茂铁'),('peroxide','非平面 H₂O₂'),('co2','线性 CO₂'),('hcn','线性 HCN'),('s4','纯S₄通用轨道模型'),('genericCs','单镜面 AB₂C 模型')]
L={}
L['molecule']=lab('molecule','01','分子实验室：选择操作，追踪每个原子','转相机不等于做对称操作。点下方按钮，再看原子匹配。',select('molecule-model','选择分子',models)+button('molecule-reset','恢复初态')+button('molecule-camera','重置相机')+'<label><span>追踪标签</span><span><input id="molecule-labels" type="checkbox" checked> 显示原子编号</span></label>','<div class="atom-keys" id="molecule-keys"></div><div class="op-buttons" id="molecule-ops"></div><div class="math-meta"><div id="molecule-matrix"></div><div id="molecule-map" class="reference-ops"></div></div>',note='理想化坐标，连接线仅用于显示局部几何。线性群的按钮是有限角度抽样，不是完整无限群。')
L['mirror']=lab('mirror','02','镜面里的点不动，镜面外的点成对','同一平面能成为NH₃的镜面，也未必能成为另一分子的镜面。',select('mirror-model','模型',[('water','H₂O'),('ammonia','NH₃'),('bf3','BF₃'),('square','正方形AB₄'),('genericCs','单镜面模型')])+select('mirror-plane','检验平面',[('vertical','包含z的竖直面'),('horizontal','xy水平面')])+slider('mirror-angle','竖直面方向角 φ / °',0,180,5,0)+button('mirror-run','播放反映')+button('mirror-twice','连续两次 = E'),note='浅蓝四边形标出候选平面。候选不一定是分子的真实镜面，程序按类型和位置检验。')
L['inversion']=lab('inversion','03','反演i与半周转动C₂，差在第三个坐标','四个外围原子是偶数，也不保证四面体有反演中心。',select('inversion-model','分子',[('sf6','SF₆ · 有i'),('methane','CH₄ · 无i'),('benzene','苯 · 有i'),('water','水 · 无i')])+select('inversion-op','操作',[('i','反演 i'),('c2','C₂(z)')])+button('inversion-run','播放操作'),'<div class="matrix-summary" id="inversion-point"></div>',note='额外追踪普通点(0.6,0.3,0.8)，用它区分i与C₂；不能只观察恰好在原点的中心原子。')
L['rotation']=lab('rotation','04','一条Cₙ轴，究竟生成几个不同操作？','切换“复制无向副轴”，比较n为奇数与偶数时的不同。',select('rotation-n','主轴 n',[(n,n) for n in range(2,9)])+slider('rotation-m','连续转动次数 m',0,8,1,1)+select('rotation-mode','观察对象',[('atoms','n边形与编号原子'),('axes','一条无向副轴的复制')])+button('rotation-next','再转一次')+button('rotation-run','重放本次转动'),note='无向直线转180°已回到自己。仅旋转复制得到的轴数，与完整乘积闭包的轴数不是同一问题。')
L['improper']=lab('improper','05','Sₙ：单独两步都失败，合起来可以成功','默认交错乙烷：单独C₆、单独σₕ、组合S₆分别能否匹配？',select('improper-n','下标 n',[(n,n) for n in range(1,11)])+select('improper-part','施加什么',[('combined','Cₙ后σₕ · 合成Sₙ'),('rotation','只作Cₙ'),('mirror','只作σₕ'),('power','Sₙ的k次幂')])+slider('improper-k','幂 k',1,20,1,1)+button('improper-run','播放步骤')+button('improper-next','k加1'),'<div class="table-scroll" id="improper-powers"></div>',note='n=6用交错乙烷，n=4用正四面体；其它n用Sₙ生成的通用位置轨道，不声称是某个实际分子。中间压扁帧是示意。')
L['products']=lab('products','06','把两个操作的乘积算给普通点看','先看坐标链，再交换两步；是否仍得到同一个矩阵？',select('products-pair','操作对',[('c2','C₂(x)与C₂(y)'),('c4v','σ(xz)与C₄(z)'),('ih','C₂(z)与σₕ'),('noncommute','σ(xz)与C₃(z)')])+button('products-run','依次播放')+button('products-swap','交换先后'),'<div class="step-list" id="products-chain"></div><div id="products-matrix"></div>',note='跟踪普通点，不把任意一组非对称点当作某个分子的对称模型。总矩阵按“后作用 × 先作用”计算。')
L['orbits']=lab('orbits','07','同样是F，为什么PF₅轴向与赤道不等价？','点一个原子，金色标出能被群操作送到的位置。',select('orbits-model','模型',[('pf5','PF₅'),('water','H₂O'),('methane','CH₄'),('sf6','SF₆'),('benzene','苯')])+select('orbits-atom','追踪原子',[(0,'载入后选择')])+button('orbits-next','用下一个操作移动'),'<div class="label-cloud" id="orbits-list"></div>',note='这里固定构型，只允许点群操作。内部重排可能在实验上交换环境，但不是本图的点群操作。')
L['planes']=lab('planes','08','两次镜像 = 两倍夹角的转动','角度从30°改到60°；交换镜面次序，观察转动方向。',slider('planes-angle','两面夹角 φ / °',0,90,1,30)+button('planes-run','播放两次镜像')+button('planes-swap','交换两镜面'),'<div class="matrix-summary" id="planes-equation"></div>',note='这是一般几何变换。只有这些平面确实都是某个分子的对称面时，才能据此推断该分子的其它操作。')
L['chirality']=lab('chirality','09','镜像能否靠真转动叠合？','比较四种不同取代基的四面体与没有σ、i的纯S₄模型。',select('chirality-model','原物',[('chiral','四种不同配体 · C₁'),('s4','纯S₄ · 无σ也无i'),('methane','四个相同H · T_d'),('peroxide','非平面H₂O₂ · C₂')])+select('chirality-view','显示',[('mirror','右侧显示镜像'),('overlap','尝试按已知对称性叠合')])+button('chirality-run','播放叠合步骤'),note='手性判据针对刚性指定构型；实际是否可分离或有净旋光还受动态互变、混合组成等影响。C₁示例用有向体积证明镜像不能被真转动变回。')
L['families']=lab('families','10','从几个生成元长成完整点群','同一Cₙ，添加σₕ、竖直面或副C₂会多出哪些操作？',select('families-type','点群族',[(x,x) for x in ['Cn','Cnv','Cnh','Dn','Dnh','Dnd','Sn']])+select('families-n','n',[(n,n) for n in range(2,9)])+button('families-next','显示下一层闭包')+button('families-all','显示全部操作'),'<div class="op-buttons" id="families-ops"></div><div class="step-flow" id="families-generators"></div>',note='生成元标为a、b、c。所示通用位置轨道按这些操作构建，只用于群结构，不拟合真实化学分子。')
L['polyhedra']=lab('polyhedra','11','转动五种正多面体，数轴而不是数外观','立方体与八面体不同形，为什么同为O_h？',select('polyhedra-shape','形体',[('tetra','正四面体'),('cube','立方体'),('octa','正八面体'),('dodeca','正十二面体'),('ico','正二十面体'),('cubocta','立方八面体 · 非正多面体')])+select('polyhedra-subgroup','检视操作',[('full','完整点群'),('proper','只保留真转动')])+button('polyhedra-next','施加下一个操作')+button('polyhedra-spin','开关自动转视角'),'<div class="facts-grid" id="polyhedra-counts"></div><div class="op-buttons" id="polyhedra-ops"></div>',note='所有形体由坐标和棱自动绘制。正十二面体由正二十面体的面中心构造，二者共用同一组I_h矩阵。')
L['classes']=lab('classes','12','C₄与C₄v、T与T_d：母群改变，类也改变','选同一个转动，看相反方向的幂何时能合成一类。',select('classes-group','母群',[('C4','C₄'),('C4v','C₄v'),('T','T'),('Td','T_d'),('Th','T_h'),('Oh','O_h'),('Ih','I_h')])+select('classes-a','群元素',[(0,'E')])+button('classes-next','用下一个X作共轭'),'<div class="tiles" id="classes-list"></div>',note='先用全部矩阵求X⁻¹AX，再按不同输出分组。操作名只是说明，类的划分来自实际共轭计算。')
L['classifier']=lab('classifier','13','一步一步判点群，而不是猜名字','选择已知例子，或手动更改特征；面板显示采用了哪条分支。',select('classifier-example','例子',[('water','水'),('ammonia','氨'),('allene','丙二烯'),('peroxide','非平面过氧化氢'),('benzene','苯'),('pf5','PF₅'),('ferrocene','交错二茂铁'),('s4','只有S₄'),('custom','手动给定特征')])+select('classifier-special','特殊情况',[('none','不是特殊群'),('C∞v','线性异端 C∞v'),('D∞h','线性等端 D∞h'),('Td','T_d'),('Oh','O_h'),('Ih','I_h')])+select('classifier-n','最高真轴 n',[(n,n) for n in range(1,9)])+select('classifier-c2','n条垂直C₂',[('0','没有'),('1','有')])+select('classifier-plane','额外镜面',[('none','没有'),('h','水平σₕ'),('v','竖直σᵥ'),('d','二面σ_d')])+select('classifier-onlys','只有Sₙ生成？',[('0','否'),('4','只有S₄'),('6','只有S₆'),('8','只有S₈')]),'<div class="step-flow" id="classifier-flow"></div>',canvas=False,note='手动模式输入的是已检查的几何特征，不是对任意分子坐标进行全自动点群识别。矛盾特征会提示重新核查。')
L['conformation']=lab('conformation','14','连续扭一点，点群可能突然跳变','中间构象也要重新找副轴，不能只看最高主轴。',select('conformation-model','变化对象',[('ammonia','NH₃逐渐压平'),('peroxide','H₂O₂扭转'),('ferrocene','二茂铁两环扭转'),('ethane','乙烷两端扭转')])+slider('conformation-value','参数',0,100,1,55)+button('conformation-start','第一个端点')+button('conformation-end','第二个端点')+button('conformation-op','施加当前群的下一操作'),'<div class="step-flow" id="conformation-route"></div>',note='构象参数的改变是内部结构变形，不是对称操作。只在指定角度的固定构型上计算当前点群；按钮施加的操作才是该构型的对称操作。')
L['decoration']=lab('decoration','15','给棱和面着色，为什么会降对称？','裸多面体的操作不一定保留颜色和画线；逐个筛掉不匹配的操作。',select('decoration-type','题目模型',[('tetra','B3.3 · 四面体两条对棱着色'),('octa','B3.4 · 八面体四个交替面着色'),('cube','B3.5/6 · 立方体面中线转动'),('black','B3.7 · 面中线加交替顶点颜色')])+slider('decoration-angle','面中线旋转 θ / °',0,45,1,0)+button('decoration-next','施加下一个保留操作'),'<div class="op-buttons" id="decoration-ops"></div>',note='棱、面和线用额外标记点编码并作为完整物体的一部分匹配。它们是题目图案的计算模型，不是原子。')
L['substitution']=lab('substitution','16','把苯环上的H换成Cl，剩下哪些操作？','选择原题，或逐个点位置切换H/Cl；同时考虑完整三维操作。',select('substitution-preset','原题例子',[('mono','氯苯'),('ortho','1,2-二氯苯'),('meta','1,3-二氯苯'),('para','1,4-二氯苯'),('135','1,3,5-三氯苯'),('123','1,2,3-三氯苯'),('124','1,2,4-三氯苯'),('benzene','未取代苯')])+button('substitution-next','施加下一个保留操作'),'<div class="group-chips" id="substitution-sites"></div><div class="op-buttons" id="substitution-ops"></div>',note='假定理想平面且替换不改变其它几何参数；保留操作从母群D₆h的24项中逐一筛选。')
text=(R/'第三章_分子对称性和对称群.md').read_text()
for key,val in L.items():
 marker='<!-- LAB:'+key+' -->';assert marker in text; text=text.replace(marker,val)
protected=[]
def save(s):protected.append(s);return f'ZZKEEP{len(protected)-1}ZZ'
text=re.sub(r'<section class="demo".*?</section>',lambda m:save(m[0]),text,flags=re.S)
text=re.sub(r'\$\$(.*?)\$\$',lambda m:save('<div class="math-block" tabindex="0" aria-label="公式，可横向滚动">'+convert(m[1].strip(),display='block')+'</div>'),text,flags=re.S)
text=re.sub(r'\$([^$\n]+)\$',lambda m:save(convert(m[1],display='inline')),text)
# Protect conventional ASCII point-group subscripts from Markdown underscore emphasis.
text=re.sub(r'\b([CDSTOI])_([a-z0-9]+)',lambda m:save('<span class="group-symbol">'+m[1]+'<sub>'+m[2]+'</sub></span>'),text)
prose=str(markdown2.markdown(text,extras=['tables','fenced-code-blocks']))
submap=str.maketrans('₀₁₂₃₄₅₆₇₈₉ₙ','0123456789n')
def group_text(t):
 return re.sub(r'([CDSTOI])([₀₁₂₃₄₅₆₇₈₉ₙ∞]+)([hvdis]?)',lambda m:'<span class="group-symbol">'+m[1]+'<sub>'+m[2].translate(submap)+m[3]+'</sub></span>',t)
prose=re.sub(r'(^|>)([^<]*)(?=<|$)',lambda m:m[1]+group_text(m[2]),prose)

for i,t in enumerate(protected):
 key=f'ZZKEEP{i}ZZ';prose=prose.replace('<p>'+key+'</p>',t).replace(key,t)
prose=re.sub(r'<table>(.*?)</table>',r'<div class="table-scroll"><table>\1</table></div>',prose,flags=re.S)
# Associate each original section with its actual Chinese page span.
spans=[(13,13),(13,14),(14,16),(16,16),(16,19),(19,20),(20,22),(22,23),(23,24),(24,27),(27,31),(31,35),(35,38),(38,39),(39,42)]
toc=[]
def heading(m):
 i=len(toc)+1;id='section-'+str(i);toc.append((id,re.sub('<[^>]+>','',m[1])));return f'<h2 id="{id}">'+m[1]+'</h2>'
prose=re.sub(r'<h2>(.*?)</h2>',heading,prose,flags=re.S)
# Original scan pages remain local, unchanged and lazy-loaded.
asset=R/'assets/原文对照';asset.mkdir(exist_ok=True)
for book in range(13,46):shutil.copy2(R/f'核对资料/zh-{book+15:03d}.jpg',asset/f'中文-书页{book:02d}.jpg')
for book in range(61,68):shutil.copy2(R/f'核对资料/en-{book+9:03d}.jpg',asset/f'英文-书页{book:02d}.jpg')
def original(a,b,lang='中文'):
 return '<details class="original-pages"><summary>展开'+lang+'原页 '+str(a)+('–'+str(b) if a!=b else '')+' · 原话、原图对照</summary><p class="image-note">来自用户提供的第三版扫描本；书页与PDF页数不同。保留原始页面字样，用于本地对读。</p>'+''.join(f'<a href="assets/原文对照/{lang}-书页{k:02d}.jpg" target="_blank"><img class="source-page" loading="lazy" src="assets/原文对照/{lang}-书页{k:02d}.jpg" alt="{lang}第三版第三章书页{k}，点击查看原尺寸"></a>' for k in range(a,b+1))+'</details>'
# Insert page comparison before the next section starts.
for i,(a,b) in reversed(list(enumerate(spans,1))):
 marker=f'<h2 id="section-{i+1}">';assert marker in prose
 prose=prose.replace(marker,original(a,b)+marker,1)
prose=prose.replace('<h2 id="section-17">','<h3 id="original-exercises">原题逐页对照：两版全部习题与图形</h3>'+original(42,45)+original(61,67,'英文')+'<h2 id="section-17">')
